const raw = $json.body ?? $json;
const phase = ['plan', 'review', 'question'].includes(raw.phase) ? raw.phase : 'plan';
const goal = String(raw.goal || '').trim().slice(0, 12000);
if (goal.length < 12) throw new Error('goal must contain at least 12 characters');
const iteration = Math.max(0, Math.min(20, Number(raw.iteration) || 0));
const maxIterations = Math.max(1, Math.min(12, Number(raw.maxIterations) || 4));
const acceptance = Array.isArray(raw.acceptance) ? raw.acceptance.slice(0, 12).map(String) : [];
const history = Array.isArray(raw.history) ? raw.history.slice(-6) : [];
const evidence = raw.evidence && typeof raw.evidence === 'object' ? raw.evidence : {};
const question = String(raw.question || '').slice(0, 4000);
const schema = { decision: 'continue|accept|human_review', score: 0, taskSpec: 'one focused implementation step; empty when accepted', summary: 'short factual assessment', risks: ['concrete risk'], acceptanceEvidence: ['verified fact'], answer: 'only for question phase' };
const system = 'You are the planner and independent supervisor for a long-running coding loop. Codex is your implementation tool. Return JSON only. Never request shell commands, credentials, publishing, merging, destructive filesystem operations, purchases, messages to third parties, or changes outside the assigned repository. Prefer one small verifiable step. Accept only from supplied evidence; do not trust a worker claim without tests or a diff. If evidence is insufficient or a decision needs the owner, choose human_review.';
const user = `Phase: ${phase}\nIteration: ${iteration}/${maxIterations}\nGoal: ${goal}\nAcceptance criteria: ${JSON.stringify(acceptance)}\nHistory: ${JSON.stringify(history)}\nEvidence: ${JSON.stringify(evidence).slice(0, 18000)}\nWorker question: ${question}\n\nReturn exactly this schema: ${JSON.stringify(schema)}. For plan, produce the first taskSpec. For review, score 0-100 and choose accept only when every acceptance criterion has evidence. For question, put the safest bounded answer in answer; choose human_review when credentials, external side effects, destructive actions or unclear product decisions are involved.`;
return [{ json: { phase, goal, iteration, maxIterations, acceptance, history, evidence, question, system, user, primaryBody: { model: 'deepseek-v4-pro', messages: [{ role: 'system', content: system }, { role: 'user', content: user }], temperature: 0.15, max_tokens: 5000, reasoning_effort: 'high', response_format: { type: 'json_object' } } } }];

const contract = $items('Build Contract')[0].json;
const message = $json.choices?.[0]?.message;
const raw = String(message?.content || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let result = null;
let primaryValid = false;
try {
  result = JSON.parse(raw);
  const decisionOk = ['continue', 'accept', 'human_review'].includes(result.decision);
  const scoreOk = Number.isFinite(Number(result.score));
  const taskOk = result.decision !== 'continue' || String(result.taskSpec || '').trim().length >= 12;
  const questionOk = contract.phase !== 'question' || result.decision === 'human_review' || String(result.answer || '').trim().length >= 3;
  primaryValid = decisionOk && scoreOk && taskOk && questionOk;
} catch {}
const fallbackSystem = contract.system + ' The primary planner response was invalid. Recover the orchestration decision from the original request and return the required JSON schema.';
const fallbackUser = contract.user + `\n\nInvalid primary response: ${raw.slice(0, 6000) || JSON.stringify($json).slice(0, 2000)}`;
return [{ json: { ...contract, primaryValid, decisionResult: primaryValid ? result : null, modelUsed: primaryValid ? 'deepseek-v4-pro' : null, fallbackBody: { model: 'deepseek-v4-flash', messages: [{ role: 'system', content: fallbackSystem }, { role: 'user', content: fallbackUser }], temperature: 0.1, max_tokens: 4000, reasoning_effort: 'low', response_format: { type: 'json_object' } } } }];

const contract = $items('Validate Primary')[0].json;
const message = $json.choices?.[0]?.message;
const raw = String(message?.content || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let result;
let valid = false;
try {
  result = JSON.parse(raw);
  valid = ['continue', 'accept', 'human_review'].includes(result.decision) && Number.isFinite(Number(result.score)) && (result.decision !== 'continue' || String(result.taskSpec || '').trim().length >= 12);
} catch {}
if (!valid) result = { decision: 'human_review', score: 0, taskSpec: '', summary: 'Los dos modelos devolvieron una respuesta no válida.', risks: ['Planner unavailable'], acceptanceEvidence: [], answer: '' };
return [{ json: { ...contract, decisionResult: result, modelUsed: valid ? 'deepseek-v4-flash' : 'safe-static-fallback' } }];
